/**
 * Semantic scene snapshots and diffs — the differential oracle for the
 * web-native migration.
 *
 * The pre-migration oracle compared rendered frames pixel by pixel.  That stops
 * being meaningful once rendering is no longer pixel-aligned (`Create` is
 * arc-length parameterized, text is measured by the browser, 3D is three.js).
 * This module replaces it with a *semantic* comparison: the object tree, each
 * object's class, position, size, paint, z-order and point count, plus the
 * animation durations, compared with explicit tolerances.
 *
 * Both halves are pure and DOM-free, so a snapshot can be produced under Node
 * (headless scene run) and in a browser, and two snapshots from either
 * environment compare.
 */
import type { Mobject } from "../mobject/mobject.js";
/** One node of a semantic snapshot. */
export interface SemanticNode {
    /** Constructor name (`Circle`, `Text`, `VGroup`, ...). */
    cls: string;
    /** Centre in world coordinates. */
    center: [number, number, number];
    /** Bounding-box size. */
    size: [number, number];
    /** Uniform fill colour as `#rrggbb`, or null when the fill is a gradient. */
    fill: string | null;
    fill_opacity: number;
    stroke: string | null;
    stroke_opacity: number;
    stroke_width: number;
    z_index: number;
    /** Number of stored points (0 for groups and DOM content). */
    points: number;
    /** Hash of the DOM content payload, when the mobject renders as content. */
    content: string | null;
    children: SemanticNode[];
}
/** A whole scene's semantic state at one point in time. */
export interface SemanticSnapshot {
    /** Scene class name. */
    scene: string;
    /** Cumulative play index this state was taken after (0 = before any play). */
    play: number;
    /** Sum of the run times of the animations played so far, in seconds. */
    time: number;
    objects: SemanticNode[];
}
export interface SnapshotOptions {
    /** Include submobjects (default true). */
    children?: boolean;
}
/** One mobject (and optionally its family) as a semantic node. */
export declare function semantic_node(mobject: Mobject, options?: SnapshotOptions): SemanticNode;
/** Snapshot a whole scene's current visible state. */
export declare function snapshot_scene(scene: {
    mobjects: readonly Mobject[];
    constructor: {
        name: string;
    };
}, state: {
    play: number;
    time: number;
}, options?: SnapshotOptions): SemanticSnapshot;
/** One field-level difference between two snapshots or nodes. */
export interface SemanticDifference {
    /** Dotted path into the snapshot (`objects[0].children[2].center[1]`). */
    path: string;
    kind: "missing" | "extra" | "class" | "number" | "string" | "structure" | "time";
    expected: unknown;
    actual: unknown;
}
export interface DiffOptions {
    /**
     * Absolute tolerance for world-space numbers (centres, sizes, stroke width).
     * Defaults to 1e-3, which is looser than float noise but far tighter than any
     * accepted visual change.
     */
    tolerance?: number;
    /** Relative tolerance for time (default: 1e-3 of the larger value). */
    timeTolerance?: number;
    /** Compare the `children` trees (default true). */
    children?: boolean;
}
/**
 * Compare two semantic snapshots.
 *
 * Object lists are compared positionally (a scene's top-level order is
 * meaningful), the family recursively, and the elapsed `time` with a relative
 * tolerance.  An empty result means "semantically identical within tolerance".
 */
export declare function diff_snapshots(expected: SemanticSnapshot, actual: SemanticSnapshot, options?: DiffOptions): SemanticDifference[];
/** Human-readable one-line rendering of a difference (CLI output). */
export declare function format_difference(difference: SemanticDifference): string;
